'use strict';
// Eligibility is an explicit, time-stamped observation, not today's constituents
// projected backwards. No table means legacy behavior, never verified provenance.
const validDate=d=>typeof d==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(d)&&Number.isFinite(Date.parse(d))&&new Date(d).toISOString().slice(0,10)===d;
function validateUniverseHistory(rows){if(rows==null)return;if(!Array.isArray(rows)||!rows.length||rows.length>100000)throw Error('历史股票池无效');const groups=new Map();for(const row of rows){if(!row||!/^\d{6}$/.test(row.symbol)||!validDate(row.from)||!validDate(row.through)||row.from>row.through||typeof row.eligible!=='boolean'||typeof row.source!=='string'||!row.source.trim()||typeof row.knownAt!=='string'||!/(Z|[+-]\d{2}:\d{2})$/.test(row.knownAt)||!Number.isFinite(Date.parse(row.knownAt)))throw Error('历史股票池缺少日期、来源或已知时点');if(row.sector!==undefined&&(typeof row.sector!=='string'||!row.sector||row.sector.length>80))throw Error('行业分类无效');if(!groups.has(row.symbol))groups.set(row.symbol,[]);groups.get(row.symbol).push(row);}
 for(const list of groups.values()){list.sort((a,b)=>a.from.localeCompare(b.from));for(let i=1;i<list.length;i++)if(list[i].from<=list[i-1].through)throw Error('历史股票池区间重叠');}}
function universeObservation(rows,symbol,date,{at='close'}={}){if(rows==null)return {eligible:true,verified:false,sector:null};if(!validDate(date)||!['open','close'].includes(at))throw Error('股票池决策日期无效');const stamp=Date.parse(date+(at==='open'?'T09:30:00+08:00':'T15:00:00+08:00'));const row=rows.find(r=>r.symbol===symbol&&r.from<=date&&date<=r.through&&Date.parse(r.knownAt)<=stamp);return row?{eligible:row.eligible,verified:false,sector:row.sector||null,source:row.source,knownAt:row.knownAt}:{eligible:false,verified:false,sector:null,reason:'NO_POINT_IN_TIME_MEMBERSHIP'};}
module.exports={validateUniverseHistory,universeObservation};
